import { createHsnCodeIndex } from '#/features/tools/hsn-codes.ts'
import type { HsnCodeIndex, HsnCodeRow } from '#/features/tools/hsn-codes.ts'

/**
 * Each chapter file is its own lazy chunk, so the code data never enters the
 * main bundle and a chapter page loads only its own chapter.
 * Generated by scripts/build-hsn-data.ts.
 */
const CHAPTER_FILES = import.meta.glob<ReadonlyArray<HsnCodeRow>>('./hsn-data/*.json', {
  import: 'default',
})

function fileFor(chapterCode: string) {
  return chapterCode === '99' ? './hsn-data/sac.json' : `./hsn-data/hsn-${chapterCode}.json`
}

export async function loadChapterRows(chapterCode: string): Promise<ReadonlyArray<HsnCodeRow>> {
  const path = fileFor(chapterCode)
  return path in CHAPTER_FILES ? CHAPTER_FILES[path]() : []
}

let allRows: Promise<Array<HsnCodeRow>> | null = null

/** Every HSN and SAC code, for search. Loaded once per page session. */
export function loadAllHsnRows(): Promise<Array<HsnCodeRow>> {
  allRows ??= Promise.all(Object.values(CHAPTER_FILES).map((load) => load()))
    .then((files) => files.flat())
    .catch((error: unknown) => {
      allRows = null
      throw error
    })
  return allRows
}

let codeIndex: Promise<HsnCodeIndex> | null = null

export function loadHsnCodeIndex(): Promise<HsnCodeIndex> {
  codeIndex ??= loadAllHsnRows()
    .then(createHsnCodeIndex)
    .catch((error: unknown) => {
      codeIndex = null
      throw error
    })
  return codeIndex
}
